#include <print>

void try_change(int x) {
    x = 999;
    std::println("函数里 x = {}", x);
}

int main() {
    int a = 10;

    try_change(a);
    std::println("调用后 a = {}   ← 原稿没变", a);

    a = 42;
    try_change(a);
    std::println("再喊一次，a = {}", a);

    // 函数拿到的是那一刻值的复印件，写在副本上，原稿不动

    return 0;
}

